DEV-AR-001:
IMPORT strings.
SENTENCE raw.
INPUT(raw).
SENTENCE[] parts = strings.SPLIT(raw, " " ).
NUMBER[] values = [strings.TO_NUMBER(parts[0]), strings.TO_NUMBER(parts[1]), strings.TO_NUMBER(parts[2])].
NUMBER smallest = values[0].
LOOP (NUMBER i = 1 TILL i < 3, i++) {
    IF (values[i] < smallest) {
        smallest = values[i].
    }
}
DISPLAYNL(smallest).

