EVAL-CD-003:
IMPORT strings.
SENTENCE raw.
INPUT(raw).
SENTENCE[] parts = strings.SPLIT(raw, " " ).
NUMBER a = strings.TO_NUMBER(parts[0]).
NUMBER b = strings.TO_NUMBER(parts[1]).
NUMBER c = strings.TO_NUMBER(parts[2]).
IF (a + b <= c OR a + c <= b OR b + c <= a) {
    DISPLAYNL("INVALID").
} ELSEIF (a == b AND b == c) {
    DISPLAYNL("EQUILATERAL").
} ELSEIF (a == b OR a == c OR b == c) {
    DISPLAYNL("ISOSCELES").
} ELSE {
    DISPLAYNL("SCALENE").
}

