EVAL-FN-001:
IMPORT strings.
FUNCTION absoluteDifference(NUMBER a, NUMBER b) {
    IF (a >= b) { RETURN a - b. } ELSE { RETURN b - a. }
} RETURNS NUMBER.
SENTENCE raw.
INPUT(raw).
SENTENCE[] parts = strings.SPLIT(raw, " " ).
NUMBER x = strings.TO_NUMBER(parts[0]).
NUMBER y = strings.TO_NUMBER(parts[1]).
DISPLAYNL(absoluteDifference(x, y)).

EVAL-FN-002:
IMPORT strings.
FUNCTION square(NUMBER x) {
    RETURN x * x.
} RETURNS NUMBER.
FUNCTION sumOfSquares(NUMBER a, NUMBER b) {
    RETURN square(a) + square(b).
} RETURNS NUMBER.
SENTENCE raw.
INPUT(raw).
SENTENCE[] parts = strings.SPLIT(raw, " " ).
NUMBER a = strings.TO_NUMBER(parts[0]).
NUMBER b = strings.TO_NUMBER(parts[1]).
DISPLAYNL(sumOfSquares(a, b)).

EVAL-ST-002:
IMPORT strings.
SENTENCE text.
INPUT(text).
LOGIC same = TRUE.
NUMBER len = strings.LENGTH(text).
LOOP (NUMBER i = 0 TILL i < len / 2, i++) {
    IF (NOT strings.EQUALS(strings.CHARAT(text, i), strings.CHARAT(text, len - i - 1))) {
        same = FALSE.
    }
}
IF (same) { DISPLAYNL("PALINDROME"). } ELSE { DISPLAYNL("NOT PALINDROME"). }

EVAL-CP-001:
IMPORT strings.
SENTENCE raw.
INPUT(raw).
SENTENCE[] parts = strings.SPLIT(raw, " " ).
NUMBER a = strings.TO_NUMBER(parts[0]).
NUMBER b = strings.TO_NUMBER(parts[1]).
NUMBER greatest = 1.
NUMBER limit = a.
IF (b < limit) { limit = b. }
LOOP (NUMBER i = 1 TILL i <= limit, i++) {
    IF (a % i == 0 AND b % i == 0) { greatest = i. }
}
DISPLAYNL(greatest).

EVAL-CP-002:
NUMBER n.
INPUT(n).
LOGIC prime = TRUE.
IF (n < 2) { prime = FALSE. } ELSE {
    LOOP (NUMBER i = 2 TILL i * i <= n, i++) {
        IF (n % i == 0) { prime = FALSE. }
    }
}
IF (prime) { DISPLAYNL("PRIME"). } ELSE { DISPLAYNL("NOT PRIME"). }

FINAL-FN-001:
FUNCTION sumTo(NUMBER n) {
    NUMBER total = 0.
    LOOP (NUMBER i = 1 TILL i <= n, i++) { total += i. }
    RETURN total.
} RETURNS NUMBER.
NUMBER n.
INPUT(n).
DISPLAYNL(sumTo(n)).

